const useMyContainerWidth = (loading: boolean) => {
  const [width, setWidth] = useState(1280);
  const [mounted, setMounted] = useState(false);
  const containerRef = React.useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (loading) return;

    let observer: ResizeObserver | null = null;
    let frameId: number;

    const attachObserver = () => {
      const node = containerRef.current;
      if (node) {
        if (node.offsetWidth > 0) {
          setWidth(node.offsetWidth);
        }
        setMounted(true);

        if (typeof ResizeObserver !== 'undefined' && !observer) {
          observer = new ResizeObserver((entries) => {
            const entry = entries[0];
            if (entry && entry.contentRect.width > 0) {
              setWidth(entry.contentRect.width);
              setMounted(true);
            }
          });
          observer.observe(node);
        }
        return true;
      }
      return false;
    };

    if (!attachObserver()) {
      // Retry in next frames if containerRef hasn't attached to DOM yet
      let attempts = 0;
      const pollRef = () => {
        if (!attachObserver() && attempts < 20) {
          attempts++;
          frameId = requestAnimationFrame(pollRef);
        }
      };
      frameId = requestAnimationFrame(pollRef);
    }

    return () => {
      if (frameId) cancelAnimationFrame(frameId);
      if (observer) {
        observer.disconnect();
      }
    };
  }, [loading]);

  return { width, containerRef, mounted };
};

