  // Handle tab visibility auto-switch in Preview
  useEffect(() => {
    if (activeTab === 'preview') {
      const visibleTabs = tabs.filter(t => evaluateVisibilityRule(t.visibilityRule, moduleState));
      const isCurrentTabVisible = visibleTabs.some(t => t.id === currentTabId);
      
      if (!isCurrentTabVisible && visibleTabs.length > 0) {
        const isParent = (id: string) => tabs.some(t => t.parentId === id);
        const firstSelectable = visibleTabs.find(t => !isParent(t.id)) || visibleTabs[0];
        setCurrentTabId(firstSelectable?.id || visibleTabs[0].id);
      }
    }
  }, [activeTab, moduleState, tabs, currentTabId]);

  // Helper for single selection
  const selectedId = selectedIds.length === 1 ? selectedIds[0] : null;
  const setSelectedId = (id: string | null) => setSelectedIds(id ? [id] : []);

  // Master View column reordering and system fields selection helper states & memos
  const [draggingColumnIndex, setDraggingColumnIndex] = useState<number | null>(null);

  const selectedSystemField = React.useMemo(() => {
    if (!selectedId) return null;
    const keyCol = interfaceSettings.master.columns?.find(c => c.fieldId === '_record_key');
    const systemFieldsDef = [
      { id: '_record_key', label: keyCol?.label || 'Record Key', type: 'text' },
      { id: 'createdAt', label: 'Created Date', type: 'date' },
      { id: 'createdBy', label: 'Created By', type: 'user' },
      { id: 'updatedAt', label: 'Updated Date', type: 'date' },
      { id: 'status', label: 'Status', type: 'select' },
      { id: 'nextStep', label: 'Next Step (Workflow)', type: 'text' },
      { id: 'assigneeId', label: 'Assignee', type: 'user' },
      { id: 'participantIds', label: 'Participants', type: 'multi-user' }
    ];
    return systemFieldsDef.find(sf => sf.id === selectedId) || null;
  }, [selectedId, interfaceSettings.master.columns]);

  const activeColumns = React.useMemo(() => {
    const systemFieldsDef = [
      { id: 'createdAt', label: 'Created Date', type: 'date' },
      { id: 'createdBy', label: 'Created By', type: 'user' },
      { id: 'updatedAt', label: 'Updated Date', type: 'date' },
      { id: 'status', label: 'Status', type: 'select' },
      { id: 'nextStep', label: 'Next Step (Workflow)', type: 'text' },
      { id: 'assigneeId', label: 'Assignee', type: 'user' },
      { id: 'participantIds', label: 'Participants', type: 'multi-user' }
    ];

    const configured = interfaceSettings.master.columns || [];

    if (configured.length > 0) {
      return configured
        .filter(c => c.visible !== false && c.fieldId !== '_record_key')
        .map(c => {
          const custom = displayFields.find(df => df.id === c.fieldId);
          if (custom) return { ...custom, ...c, fieldLabel: custom.label, label: c.label || custom.label };
          const sys = systemFieldsDef.find(sf => sf.id === c.fieldId);
          if (sys) return { ...sys, ...c, fieldLabel: sys.label, label: c.label || sys.label };
          return null;
        })
        .filter(Boolean) as any[];
    }
    
    return displayFields.filter(f => f.showInTable === true);
  }, [displayFields, interfaceSettings.master.columns]);


  // --- Helpers ---
  

  const resolveCollisionsInArray = useCallback((triggerField: Field, fields: Field[]) => {

    const otherFields = fields.filter(f => f.id !== triggerField.id);
    
    const items: any[] = otherFields.map(f => ({
      id: f.id,
      x: (f.startCol || 1) - 1,
      y: f.rowIndex || 0,
      w: f.colSpan || 12,
      h: calculateHeight(f)
    }));

    const triggerItem = {
      id: triggerField.id,
      x: (triggerField.startCol || 1) - 1,
      y: triggerField.rowIndex || 0,
      w: triggerField.colSpan || 12,
      h: calculateHeight(triggerField)
    };

    const resolvedItems = resolveCollisions(triggerItem, items);

    return resolvedItems.map(ri => {
      const original = ri.id === triggerField.id ? triggerField : otherFields.find(f => f.id === ri.id);
      if (!original) return null;
      return {
        ...original,
        startCol: ri.x + 1,
        rowIndex: ri.y,
        colSpan: ri.w
      } as Field;
    }).filter(Boolean) as Field[];
  }, [resolveCollisions]);

  const normalizeLayout = (currentLayout: Field[]): Field[] => {
    if (!currentLayout || currentLayout.length === 0) return [];
    
    // Filter out temporary placeholder indicators from persisted layout
    const cleanFields = currentLayout.filter(f => f.id !== 'placeholder' && f.id !== '__drop_zone_indicator__' && f.type !== 'placeholder');

    // Group fields by tabId and parentId to normalize each context independently
    const groups: Record<string, Field[]> = {};
    cleanFields.forEach(f => {
      const key = `${f.tabId || 'default'}-${f.parentId || 'root'}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(f);
    });

    const resultLayout: Field[] = [];

    // Process each group context (tab + parent)
    Object.values(groups).forEach(groupFields => {
      // 1. Recursively normalize nested fields first to ensure heights are correct
      const withNormalizedChildren = groupFields.map(f => {
        if (f.fields && f.fields.length > 0) {
          return { ...f, fields: normalizeLayout(f.fields) };
        }
        return f;
      });

      // 2. Gravity Compaction: Sort by row then col
      const sorted = [...withNormalizedChildren].sort((a, b) => {
        if ((a.rowIndex || 0) !== (b.rowIndex || 0)) return (a.rowIndex || 0) - (b.rowIndex || 0);
        return (a.startCol || 1) - (b.startCol || 1);
      });

      // 3. Track column tops for this context
      const columnTops = new Array(13).fill(0);
      
      const normalizedGroup = sorted.map(f => {
        const startCol = f.startCol || 1;
        const colSpan = f.colSpan || 12;
        const height = calculateHeight(f);
        const endCol = Math.min(13, startCol + colSpan);

        // Find highest available row in spanning columns
        let targetRow = 0;
        for (let i = startCol; i < endCol; i++) {
          targetRow = Math.max(targetRow, columnTops[i]);
        }

        // Smart Gravity: If it's a placeholder, prefer its current rowIndex 
        // to give the user precise control, but still respect collisions with items above.
        let newRowIndex = targetRow;
        if (f.id === 'placeholder') {
          newRowIndex = Math.max(targetRow, f.rowIndex || 0);
        }
        for (let i = startCol; i < endCol; i++) {
          columnTops[i] = newRowIndex + height;
        }

        return {
          ...f,
          rowIndex: newRowIndex
        };
      });

      resultLayout.push(...normalizedGroup);
    });

    return resultLayout;
  };


  const generateId = () => Math.random().toString(36).substring(2, 11);
  
  const generateSlug = (label: string, fields: Field[], currentFieldId?: string): string => {
    // 1. Basic slugification
    let slug = label
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9_]/g, '_')
      .replace(/_+/g, '_')
      .replace(/^_+|_+$/g, '');
    
    if (!slug) slug = 'field';
    
    // 2. Uniqueness check
    const getAllSlugs = (f: Field[]): string[] => {
      let slugs: string[] = [];
      f.forEach(field => {
        if (field.id !== currentFieldId && field.name) slugs.push(field.name);
        if (field.fields) slugs.push(...getAllSlugs(field.fields));
      });
      return slugs;
    };
    
    const existingSlugs = getAllSlugs(fields);
    let finalSlug = slug;
    let counter = 1;
    
    while (existingSlugs.includes(finalSlug)) {
      finalSlug = `${slug}_${counter}`;
      counter++;
    }
    
    return finalSlug;
  };

  const createField = (rawType: FieldType | string): Field => {
    const id = `field-${generateId()}`;
    const resolvedType: FieldType =
      rawType === 'team_select' || rawType === 'position_select' || rawType === 'multi_user'
        ? 'lookup'
        : rawType === 'global_list'
        ? 'select'
        : (rawType as FieldType);

    const presetLabelMap: Record<string, string> = {
      party: 'Directory Entity',
      team_select: 'Team',
      position_select: 'Position / Role',
      global_list: 'Global List',
      multi_user: 'Users',
      ai_summary: 'AI Summary',
      connector: 'API Connector',
    };
    const label =
      presetLabelMap[rawType] ||
      `New ${resolvedType.charAt(0).toUpperCase() + resolvedType.slice(1).replace('_', ' ')}`;
    const name = generateSlug(label, layout, id);

    const presetPlaceholderMap: Record<string, string> = {
      party: 'Search people or organisations in Directory...',
      team_select: 'Select team...',
      position_select: 'Select position or role...',
      global_list: 'Select from global list...',
      multi_user: 'Select users...',
      ai_summary: 'AI Summary will be generated after saving.',
    };
    
    return {
      id,
      name,
      type: resolvedType,
      label,
      placeholder:
        presetPlaceholderMap[rawType] ||
        (['select', 'lookup', 'user'].includes(resolvedType) 
          ? `Select ${resolvedType.replace('_', ' ')}...`
          : `Enter ${resolvedType.replace('_', ' ')}...`),
      helperText: '',
      required: false,
      currencySymbol: '$',
      options: ['Option 1', 'Option 2'],
      calculationLogic: '',
      targetModuleId: '',
      ...(rawType === 'party'
        ? {
            lookupSource: 'platform' as const,
            platformEntity: 'modules' as const,
            targetPlatformModuleId: 'people-organisations',
            partyTypeFilter: 'ALL' as const,
            classificationFilter: 'ALL',
            allowInlineCreate: true,
          }
        : rawType === 'team_select'
        ? {
            lookupSource: 'platform' as const,
            platformEntity: 'teams' as const,
          }
        : rawType === 'position_select'
        ? {
            lookupSource: 'platform' as const,
            platformEntity: 'positions' as const,
          }
        : rawType === 'multi_user'
        ? {
            lookupSource: 'platform' as const,
            platformEntity: 'users' as const,
            allowMultiple: true,
          }
        : rawType === 'global_list'
        ? {
            optionsSource: 'global_list' as const,
          }
        : {}),
      colSpan: ['ai_summary', 'connector', 'sub_module', 'relationship_m2m'].includes(resolvedType) ? 12 : 6,
      startCol: 1,
      rowIndex: layout.length,
      tabId: currentTabId,
      showInTable: false,
      fields: isContainerField(resolvedType) ? [] : undefined
    };
  };

  // --- DnD Handlers ---

  const handleDragStart = (e: React.DragEvent, data: any) => {
    e.dataTransfer.setData('application/json', JSON.stringify(data));
    e.dataTransfer.effectAllowed = 'move';
    setActiveDragItem(data);
    
    // Resolve label and icon
    let label = 'New Field';
    let icon: any = null;
    if (data.type === 'field') {
      const fieldDef = FIELD_CATEGORIES.flatMap(c => c.fields).find(f => f.id === data.fieldType);
      label = fieldDef?.label || 'New Field';
      icon = fieldDef?.icon || null;
    } else if (data.type === 'move') {
      const field = findFieldRecursive(layout, data.fieldId);
      label = field?.label || 'Field';
      const fieldDef = FIELD_CATEGORIES.flatMap(c => c.fields).find(f => f.id === field?.type);
      icon = fieldDef?.icon || null;
      e.dataTransfer.setData('fieldId', data.fieldId);
    }
    
    setDraggedFieldInfo({ ...data, label, icon });
  };

  const handleDragEnd = () => {
    setActiveDragItem(null);
    setDraggedFieldInfo(null);
    setDragOverInfo(null);
    setPreviewLayout(null);
  };

  const handleColumnDragStart = (e: React.DragEvent, index: number) => {
    e.dataTransfer.setData('text/plain', String(index));
    e.dataTransfer.effectAllowed = 'move';
    setDraggingColumnIndex(index);
  };

  const handleColumnHeaderDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    e.stopPropagation();
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
    const x = e.clientX - rect.left;
    const width = rect.width;
    const side = x < width / 2 ? 'left' : 'right';
    const targetIdx = side === 'left' ? index : index + 1;
    
    setTableDropIndicator({
      index: targetIdx,
      hoveredIndex: index,
      side: side
    });
  };

  const handleKeyHeaderDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setTableDropIndicator({
      index: 0,
      hoveredIndex: -1,
      side: 'right'
    });
  };

  const handleColumnDragLeave = () => {
    setTableDropIndicator(null);
  };

  const handleColumnDrop = (e: React.DragEvent, targetIndex: number) => {
    e.preventDefault();
    const sourceIndexStr = e.dataTransfer.getData('text/plain');
    if (!sourceIndexStr) return;
    const sourceIndex = parseInt(sourceIndexStr, 10);
    if (isNaN(sourceIndex)) return;

    const targetIdx = tableDropIndicator ? tableDropIndicator.index : targetIndex;

    const sourceCol = activeColumns[sourceIndex];
    if (!sourceCol) return;

    setInterfaceSettings(prev => {
      const cols = [...(prev.master.columns || [])];
      
      let currentCols = cols.length > 0 ? cols : [
        { fieldId: '_record_key', visible: true, inlineEdit: false, width: 120 },
        ...activeColumns.map(ac => ({
          fieldId: ac.id,
          visible: true,
          inlineEdit: ac.inlineEdit || false,
          width: ac.columnWidth || 200
        }))
      ];

      activeColumns.forEach(ac => {
        if (!currentCols.some(c => c.fieldId === ac.id)) {
          currentCols.push({
            fieldId: ac.id,
            visible: true,
            inlineEdit: false,
            width: 200
          });
        }
      });

      const fullSourceIdx = currentCols.findIndex(c => c.fieldId === sourceCol.id);
      if (fullSourceIdx === -1) return prev;

      let fullTargetIdx = currentCols.length;
      if (targetIdx < activeColumns.length) {
        const targetColRef = activeColumns[targetIdx];
        if (targetColRef) {
          const idxInCurrent = currentCols.findIndex(c => c.fieldId === targetColRef.id);
          if (idxInCurrent !== -1) {
            fullTargetIdx = idxInCurrent;
          }
        }
      }

      if (fullSourceIdx !== -1 && fullTargetIdx !== -1) {
        const itemToMove = currentCols[fullSourceIdx];
        const remaining = currentCols.filter((_, idx) => idx !== fullSourceIdx);
        
        let finalInsertIdx = fullTargetIdx;
        if (fullSourceIdx < fullTargetIdx) {
          finalInsertIdx = fullTargetIdx - 1;
        }
        
        const nextCols = [
          ...remaining.slice(0, finalInsertIdx),
          itemToMove,
          ...remaining.slice(finalInsertIdx)
        ];

        return {
          ...prev,
          master: {
            ...prev.master,
            columns: nextCols
          }
        };
      }
      return prev;
    });

    setDraggingColumnIndex(null);
    setTableDropIndicator(null);
  };

  const handleTableDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
      const jsonStr = e.dataTransfer.getData('application/json');
      if (!jsonStr) return;
      const data = JSON.parse(jsonStr);
      if (data.type === 'master-column-add') {
        const { fieldId, isSystem } = data;
        
        const targetIdx = tableDropIndicator ? tableDropIndicator.index : activeColumns.length;

        if (isSystem) {
          setInterfaceSettings(prev => {
            const cols = prev.master.columns || [];
            let currentCols = cols.length > 0 ? [...cols] : [
              { fieldId: '_record_key', visible: true, inlineEdit: false, width: 120 },
              ...activeColumns.map(ac => ({
                fieldId: ac.id,
                visible: true,
                inlineEdit: ac.inlineEdit || false,
                width: ac.columnWidth || 200
              }))
            ];

            const existingIdx = currentCols.findIndex(c => c.fieldId === fieldId);
            let newColItem: { fieldId: string, visible: boolean, inlineEdit: boolean, width?: number, label?: string } = { fieldId, visible: true, inlineEdit: false, width: 120 };
            
            if (existingIdx !== -1) {
              newColItem = { ...currentCols[existingIdx], visible: true };
              currentCols.splice(existingIdx, 1);
            }

            let fullInsertIdx = currentCols.length;
            if (targetIdx < activeColumns.length) {
              const targetColRef = activeColumns[targetIdx];
              if (targetColRef) {
                const idxInCurrent = currentCols.findIndex(c => c.fieldId === targetColRef.id);
                if (idxInCurrent !== -1) {
                  fullInsertIdx = idxInCurrent;
                }
              }
            }

            currentCols.splice(fullInsertIdx, 0, newColItem);

            return {
              ...prev,
              master: {
                ...prev.master,
                columns: currentCols
              }
            };
          });
          setSelectedId(fieldId);
          toast.success("System column added to table!");
          setTableDropIndicator(null);
          return;
        }

        updateField(fieldId, { showInTable: true });

        setInterfaceSettings(prev => {
          const cols = prev.master.columns || [];
          let currentCols = cols.length > 0 ? [...cols] : [
            { fieldId: '_record_key', visible: true, inlineEdit: false, width: 120 },
            ...activeColumns.map(ac => ({
              fieldId: ac.id,
              visible: true,
              inlineEdit: ac.inlineEdit || false,
              width: ac.columnWidth || 200
            }))
          ];

          const existingIdx = currentCols.findIndex(c => c.fieldId === fieldId);
          let newColItem: { fieldId: string, visible: boolean, inlineEdit: boolean, width?: number, label?: string } = { fieldId, visible: true, inlineEdit: false, width: 200 };
          
          if (existingIdx !== -1) {
            newColItem = { ...currentCols[existingIdx], visible: true };
            currentCols.splice(existingIdx, 1);
          }

          let fullInsertIdx = currentCols.length;
          if (targetIdx < activeColumns.length) {
            const targetColRef = activeColumns[targetIdx];
            if (targetColRef) {
              const idxInCurrent = currentCols.findIndex(c => c.fieldId === targetColRef.id);
              if (idxInCurrent !== -1) {
                fullInsertIdx = idxInCurrent;
              }
            }
          }

          currentCols.splice(fullInsertIdx, 0, newColItem);

          return {
            ...prev,
            master: {
              ...prev.master,
              columns: currentCols
            }
          };
        });

        setSelectedId(fieldId);
        toast.success("Column added to table view!");
      }
    } catch (err) {
      console.error(err);
    }
    setTableDropIndicator(null);
  };

  const handleCardsDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
      const jsonStr = e.dataTransfer.getData('application/json');
      if (!jsonStr) return;
      const data = JSON.parse(jsonStr);
      if (data.type === 'master-column-add') {
        const { fieldId } = data;
        setInterfaceSettings((prev: any) => {
          const cardFields = prev.master.cardFields || [];
          const currentFields = cardFields.length > 0
            ? cardFields
            : displayFields.slice(1, 4).map(df => ({ fieldId: df.id, visible: true }));

          if (currentFields.some((cf: any) => cf.fieldId === fieldId)) {
            toast.success("Field already active on cards!");
            return {
              ...prev,
              master: {
                ...prev.master,
                cardFields: currentFields.map((cf: any) => cf.fieldId === fieldId ? { ...cf, visible: true } : cf)
              }
            };
          }
          toast.success("Field added to cards!");
          return {
            ...prev,
            master: {
              ...prev.master,
              cardFields: [...currentFields, { fieldId, visible: true }]
            }
          };
        });
        setSelectedId('__table_settings');
      }
    } catch (err) {
      console.error(err);
    }
  };

  // ReactGridLayout layout change handler (supports any section tab)
  const handleRglLayoutChange = useCallback((newLayout: any[], targetTabId?: string) => {
    if (dragOverInfo?.active || newLayout.some(l => l.i === '__cross_drop_placeholder__')) return;
    const effectiveTabId = targetTabId || currentTabId;
    let hasChanged = false;
    const updated = layout.map(f => {
      if (f.parentId || (f.tabId !== effectiveTabId && (f.tabId || effectiveTabId !== tabs[0]?.id))) {
        return f;
      }
      const match = newLayout.find(l => l.i === f.id);
      if (match) {
        const newCol = match.x + 1;
        const newRow = match.y;
        const newSpan = match.w;
        const currentH = calculateHeight(f);
        const newRowSpan = (!isContainerField(f.type) && match.h && match.h !== currentH) ? match.h : f.rowSpan;
        if (f.startCol !== newCol || f.rowIndex !== newRow || f.colSpan !== newSpan || f.rowSpan !== newRowSpan) {
          hasChanged = true;
          return {
            ...f,
            startCol: newCol,
            rowIndex: newRow,
            colSpan: newSpan,
            ...(newRowSpan !== undefined ? { rowSpan: newRowSpan } : {})
          };
        }
      }
      return f;
    });

    if (hasChanged) {
      setLayout(updated);
    }
  }, [layout, currentTabId, tabs, dragOverInfo?.active]);

  // Nested ReactGridLayout layout change handler
  const handleNestedRglLayoutChange = useCallback((parentId: string, newLayout: any[]) => {
    if (dragOverInfo?.active || newLayout.some(l => l.i === '__cross_drop_placeholder__')) return;
    let hasChanged = false;
    setLayout(prevLayout => {
      const updateRecursive = (fields: Field[]): Field[] => {
        return fields.map(f => {
          if (f.id === parentId) {
            const updatedChildFields = (f.fields || []).map(child => {
              const match = newLayout.find(l => l.i === child.id);
              if (match) {
                const newCol = match.x + 1;
                const newRow = match.y;
                const newSpan = match.w;
                const currentH = calculateHeight(child);
                const newRowSpan = (!isContainerField(child.type) && match.h && match.h !== currentH) ? match.h : child.rowSpan;
                if (child.startCol !== newCol || child.rowIndex !== newRow || child.colSpan !== newSpan || child.rowSpan !== newRowSpan) {
                  hasChanged = true;
                  return {
                    ...child,
                    startCol: newCol,
                    rowIndex: newRow,
                    colSpan: newSpan,
                    ...(newRowSpan !== undefined ? { rowSpan: newRowSpan } : {})
                  };
                }
              }
              return child;
            });
            return { ...f, fields: updatedChildFields };
          }
          if (f.fields) {
            return { ...f, fields: updateRecursive(f.fields) };
          }
          return f;
        });
      };
      const updated = updateRecursive(prevLayout);
      return hasChanged ? updated : prevLayout;
    });
  }, [dragOverInfo?.active]);

  // Move an existing field into a container (group / repeater / accordion section)
  const findNextAvailableSlot = useCallback((existing: Field[], span: number, itemH: number): { startCol: number; rowIndex: number } => {
    const w = Math.max(1, Math.min(12, span || 6));
    const rects = existing.map(ef => ({
      x: Math.max(0, (ef.startCol || 1) - 1),
      y: typeof ef.rowIndex === 'number' ? Math.max(0, ef.rowIndex) : 0,
      w: Math.max(1, Math.min(12, ef.colSpan || 12)),
      h: calculateHeight(ef),
    }));
    const maxBottom = rects.reduce((acc, r) => Math.max(acc, r.y + r.h), 0);
    const collides = (cx: number, cy: number) =>
      rects.some(r => cx < r.x + r.w && cx + w > r.x && cy < r.y + r.h && cy + itemH > r.y);

    for (let y = 0; y <= maxBottom; y++) {
      for (let x = 0; x <= 12 - w; x++) {
        if (!collides(x, y)) {
          return { startCol: x + 1, rowIndex: y };
        }
      }
    }
    return { startCol: 1, rowIndex: maxBottom };
  }, []);

  const moveFieldToContainer = useCallback((containerId: string, fieldId: string) => {
    if (!containerId || !fieldId || containerId === fieldId) return;
    const targetField = findFieldRecursive(layout, fieldId);
    const targetContainer = findFieldRecursive(layout, containerId);
    if (!targetField || !targetContainer) return;

    const isDescendant = (parentField: Field, searchId: string): boolean => {
      if (parentField.id === searchId) return true;
      return (parentField.fields || []).some(f => isDescendant(f, searchId));
    };
    if (isContainerField(targetField.type) && isDescendant(targetField, containerId)) {
      toast.error("Cannot nest a container inside itself");
      return;
    }

    setLayout(prev => {
      const cleaned = removeFieldRecursive(prev, fieldId);
      const itemSpan = targetField.colSpan || 6;
      const itemHeight = calculateHeight(targetField);

      const updatedField: Field = {
        ...targetField,
        parentId: containerId,
        tabId: undefined,
        startCol: 1,
        rowIndex: 0,
        colSpan: itemSpan
      };

      const insertIntoParent = (fields: Field[]): Field[] => {
        return fields.map(f => {
          if (f.id === containerId) {
            if (f.type === 'accordion' && updatedField.type !== 'group' && updatedField.type !== 'fieldGroup') {
              if (!f.fields || f.fields.length === 0) {
                const sectionId = `section-${Date.now()}`;
                const fieldWithParent = { ...updatedField, parentId: sectionId, startCol: 1, rowIndex: 0 };
                const newSection: Field = {
                  id: sectionId,
                  type: 'group' as FieldType,
                  label: 'Section 1',
                  name: `section_${Date.now()}`,
                  parentId: f.id,
                  fields: [fieldWithParent]
                };
                return { ...f, fields: [newSection] };
              }
              const firstSection = f.fields[0];
              const slot = findNextAvailableSlot(firstSection.fields || [], itemSpan, itemHeight);
              const fieldWithParent = { ...updatedField, parentId: firstSection.id, startCol: slot.startCol, rowIndex: slot.rowIndex };
              const updatedSections = f.fields.map((s, idx) =>
                idx === 0 ? { ...s, fields: normalizeLayout([...(s.fields || []), fieldWithParent]) } : s
              );
              return { ...f, fields: updatedSections };
            }
            const slot = findNextAvailableSlot(f.fields || [], itemSpan, itemHeight);
            const placedField = { ...updatedField, startCol: slot.startCol, rowIndex: slot.rowIndex };
            return { ...f, fields: normalizeLayout([...(f.fields || []), placedField]) };
          }
          if (f.fields) {
            return { ...f, fields: insertIntoParent(f.fields) };
          }
          return f;
        });
      };

      return normalizeLayout(insertIntoParent(cleaned));
    });
    setSelectedId(fieldId);
    toast.success(`Moved "${targetField.label}" into "${targetContainer.label}"`);
  }, [layout]);

  // Move a nested field back out to the root section canvas
  const moveFieldToRoot = useCallback((fieldId: string) => {
    const targetField = findFieldRecursive(layout, fieldId);
    if (!targetField || !targetField.parentId) return;

    // Find top-level container to preserve its tabId
    const findRootTabId = (fields: Field[], searchId: string, rootTab?: string): string | undefined => {
      for (const f of fields) {
        const currentTab = rootTab || f.tabId;
        if (f.id === searchId) return currentTab;
        if (f.fields) {
          const found = findRootTabId(f.fields, searchId, currentTab);
          if (found) return found;
        }
      }
      return undefined;
    };

    const targetTabId = findRootTabId(layout, fieldId) || currentTabId;

    setLayout(prev => {
      const cleaned = removeFieldRecursive(prev, fieldId);
      const sameTabRootFields = cleaned.filter(
        f => !f.parentId && (f.tabId === targetTabId || (!f.tabId && targetTabId === tabs[0]?.id))
      );
      const span = targetField.colSpan || 6;
      const slot = findNextAvailableSlot(sameTabRootFields, span, calculateHeight(targetField));
      const updatedField: Field = {
        ...targetField,
        parentId: undefined,
        tabId: targetTabId,
        colSpan: span,
        startCol: slot.startCol,
        rowIndex: slot.rowIndex
      };
      return normalizeLayout([...cleaned, updatedField]);
    });
    setSelectedId(fieldId);
    toast.success(`Moved "${targetField.label}" to root canvas`);
  }, [layout, currentTabId, tabs, findNextAvailableSlot]);

  // Cross-container drag-and-drop state & handlers (Root ↔ Group, Group A ↔ Group B, Any → Tab)
  const [rglDropTargetId, setRglDropTargetId] = useState<string | null>(null);
  const [rglDropTabId, setRglDropTabId] = useState<string | null>(null);
  const [rglDragCount, setRglDragCount] = useState<number>(1);

  const moveFieldsToTab = useCallback((fieldIds: string[], targetTabId: string) => {
    if (!targetTabId || fieldIds.length === 0) return;
    const targetTab = tabs.find(t => t.id === targetTabId);
    if (!targetTab) return;

    // Resolve unique top-level fields to move (if a parent group and its child are both selected, move the group once)
    const idSet = new Set(fieldIds);
    const hasSelectedAncestor = (f: Field | undefined): boolean => {
      if (!f?.parentId) return false;
      if (idSet.has(f.parentId)) return true;
      return hasSelectedAncestor(findFieldRecursive(layout, f.parentId));
    };

    const topIds = Array.from(idSet).filter(fid => {
      const f = findFieldRecursive(layout, fid);
      return Boolean(f) && !hasSelectedAncestor(f);
    });
    if (topIds.length === 0) return;

    const fieldsToMove = topIds
      .map(fid => findFieldRecursive(layout, fid))
      .filter(Boolean) as Field[];

    setLayout(prev => {
      let cleaned = prev;
      topIds.forEach(fid => {
        cleaned = removeFieldRecursive(cleaned, fid);
      });

      const targetTabExisting = cleaned.filter(
        f => !f.parentId && (f.tabId === targetTabId || (!f.tabId && targetTabId === tabs[0]?.id))
      );
      const placedOnTarget = [...targetTabExisting];
      const movedFields: Field[] = [];

      fieldsToMove.forEach(tf => {
        const span = tf.colSpan || (isContainerField(tf.type) ? 12 : 6);
        const slot = findNextAvailableSlot(placedOnTarget, span, calculateHeight(tf));
        const moved: Field = {
          ...tf,
          parentId: undefined,
          tabId: targetTabId,
          colSpan: span,
          startCol: slot.startCol,
          rowIndex: slot.rowIndex,
        };
        placedOnTarget.push(moved);
        movedFields.push(moved);
      });

      return normalizeLayout([...cleaned, ...movedFields]);
    });

    setCurrentTabId(targetTabId);
    setSelectedIds(topIds);
    toast.success(
      fieldsToMove.length === 1
        ? `Moved "${fieldsToMove[0].label}" to "${targetTab.label}"`
        : `Moved ${fieldsToMove.length} fields to "${targetTab.label}"`
    );
  }, [layout, tabs, findNextAvailableSlot]);

  const resolveDropTabAtPoint = useCallback((clientX: number, clientY: number): string | null => {
    const elements = document.elementsFromPoint(clientX, clientY);
    for (const el of elements) {
      const tabEl = (el as HTMLElement).closest?.('[data-tab-drop-id]') as HTMLElement | null;
      if (tabEl) {
        const tid = tabEl.getAttribute('data-tab-drop-id');
        if (tid) return tid;
      }
    }
    return null;
  }, []);

  const resolveDropContainerAtPoint = useCallback((draggedFieldId: string, clientX: number, clientY: number): string | null => {
    const draggedEl = document.getElementById(`canvas-field-${draggedFieldId}`);
    const elements = document.elementsFromPoint(clientX, clientY);
    for (const el of elements) {
      if (draggedEl && (el === draggedEl || draggedEl.contains(el))) continue;
      const containerEl = (el as HTMLElement).closest?.('[data-container-id]') as HTMLElement | null;
      if (containerEl) {
        if (draggedEl && (containerEl === draggedEl || draggedEl.contains(containerEl))) continue;
        const cid = containerEl.getAttribute('data-container-id');
        if (cid && cid !== draggedFieldId) {
          return cid;
        }
      }
    }
    return null;
  }, []);

  const handleRglCrossDrag = useCallback((fieldId: string, sourceParentId: string | undefined, clientX: number, clientY: number) => {
    // 1. Check if hovering over another section tab first
    const hoveredTabDropId = resolveDropTabAtPoint(clientX, clientY);
    if (hoveredTabDropId && hoveredTabDropId !== currentTabId) {
      const idsToMove = selectedIds.includes(fieldId) && selectedIds.length > 1 ? selectedIds : [fieldId];
      setRglDropTabId(prev => (prev === hoveredTabDropId ? prev : hoveredTabDropId));
      setRglDragCount(idsToMove.length);
      setRglDropTargetId(prev => (prev === '__tab__' ? prev : '__tab__'));
      setDragOverInfo(prev => (prev === null ? prev : null));
      return;
    } else {
      setRglDropTabId(prev => (prev === null ? prev : null));
    }

    const targetId = resolveDropContainerAtPoint(fieldId, clientX, clientY);
    const draggedField = findFieldRecursive(layout, fieldId);
    const span = draggedField?.colSpan || 6;
    const height = draggedField ? calculateHeight(draggedField) : 2;

    if (targetId && targetId !== sourceParentId) {
      setRglDropTargetId(prev => (prev === targetId ? prev : targetId));
      const targetContainer = findFieldRecursive(layout, targetId);
      const targetFields = (targetContainer?.fields || []).filter(f => f.id !== fieldId);
      const slot = findNextAvailableSlot(targetFields, span, height);
      setDragOverInfo(prev => {
        if (prev?.active && prev.parentId === targetId && prev.col === slot.startCol && prev.index === slot.rowIndex && prev.span === span) {
          return prev;
        }
        return {
          col: slot.startCol,
          span,
          index: slot.rowIndex,
          rowSpan: height,
          active: true,
          parentId: targetId,
          tabId: currentTabId,
        };
      });
    } else if (!targetId && sourceParentId) {
      const sourceEl = document.querySelector(`[data-container-id="${sourceParentId}"]`);
      const rect = sourceEl?.getBoundingClientRect();
      const isOutsideSource = !rect || clientX < rect.left || clientX > rect.right || clientY < rect.top || clientY > rect.bottom;
      if (isOutsideSource) {
        setRglDropTargetId(prev => (prev === '__root__' ? prev : '__root__'));
        const rootFields = layout.filter(
          f => !f.parentId && f.id !== fieldId && (f.tabId === currentTabId || (!f.tabId && currentTabId === tabs[0]?.id))
        );
        const slot = findNextAvailableSlot(rootFields, span, height);
        setDragOverInfo(prev => {
          if (prev?.active && !prev.parentId && prev.col === slot.startCol && prev.index === slot.rowIndex && prev.span === span) {
            return prev;
          }
          return {
            col: slot.startCol,
            span,
            index: slot.rowIndex,
            rowSpan: height,
            active: true,
            parentId: undefined,
            tabId: currentTabId,
          };
        });
      } else {
        setRglDropTargetId(prev => (prev === null ? prev : null));
        setDragOverInfo(prev => (prev === null ? prev : null));
      }
    } else {
      setRglDropTargetId(prev => (prev === null ? prev : null));
      setDragOverInfo(prev => (prev === null ? prev : null));
    }
  }, [resolveDropTabAtPoint, resolveDropContainerAtPoint, layout, currentTabId, tabs, selectedIds, findNextAvailableSlot]);

  const handleRglCrossDragStop = useCallback((fieldId: string, sourceParentId: string | undefined, clientX: number, clientY: number) => {
    setRglDropTargetId(null);
    setRglDropTabId(null);
    setDragOverInfo(null);

    // 1. Drop onto another section tab
    const droppedTabId = resolveDropTabAtPoint(clientX, clientY);
    if (droppedTabId && droppedTabId !== currentTabId) {
      const idsToMove = selectedIds.includes(fieldId) && selectedIds.length > 1 ? selectedIds : [fieldId];
      requestAnimationFrame(() => moveFieldsToTab(idsToMove, droppedTabId));
      return;
    }

    const targetId = resolveDropContainerAtPoint(fieldId, clientX, clientY);
    if (targetId && targetId !== sourceParentId) {
      // Defer slightly so RGL's synchronous onLayoutChange completes before reparenting
      requestAnimationFrame(() => moveFieldToContainer(targetId, fieldId));
      return;
    }
    if (!targetId && sourceParentId) {
      const sourceEl = document.querySelector(`[data-container-id="${sourceParentId}"]`);
      const rect = sourceEl?.getBoundingClientRect();
      const isOutsideSource = !rect || clientX < rect.left || clientX > rect.right || clientY < rect.top || clientY > rect.bottom;
      if (isOutsideSource) {
        requestAnimationFrame(() => moveFieldToRoot(fieldId));
      }
    }
  }, [resolveDropTabAtPoint, resolveDropContainerAtPoint, currentTabId, selectedIds, moveFieldsToTab, moveFieldToContainer, moveFieldToRoot]);

  // Create a new field directly inside a container (group / repeater / accordion section)
  const createFieldInContainer = useCallback((containerId: string, fieldType: FieldType = 'text') => {
    const targetContainer = findFieldRecursive(layout, containerId);
    if (!targetContainer) return;

    const newField = createField(fieldType);
    newField.parentId = containerId;
    newField.tabId = undefined;
    newField.colSpan = ['heading', 'divider', 'spacer', 'alert', 'html'].includes(newField.type) ? 12 : 6;
    const itemHeight = calculateHeight(newField);

    setLayout(prev => {
      const insertIntoParent = (fields: Field[]): Field[] => {
        return fields.map(f => {
          if (f.id === containerId) {
            if (f.type === 'accordion' && newField.type !== 'group' && newField.type !== 'fieldGroup') {
              if (!f.fields || f.fields.length === 0) {
                const sectionId = `section-${Date.now()}`;
                const fieldWithParent = { ...newField, parentId: sectionId, startCol: 1, rowIndex: 0 };
                const newSection: Field = {
                  id: sectionId,
                  type: 'group' as FieldType,
                  label: 'Section 1',
                  name: `section_${Date.now()}`,
                  parentId: f.id,
                  fields: [fieldWithParent]
                };
                return { ...f, fields: [newSection] };
              }
              const firstSection = f.fields[0];
              const slot = findNextAvailableSlot(firstSection.fields || [], newField.colSpan || 6, itemHeight);
              const fieldWithParent = { ...newField, parentId: firstSection.id, startCol: slot.startCol, rowIndex: slot.rowIndex };
              const updatedSections = f.fields.map((s, idx) =>
                idx === 0 ? { ...s, fields: normalizeLayout([...(s.fields || []), fieldWithParent]) } : s
              );
              return { ...f, fields: updatedSections };
            }
            const slot = findNextAvailableSlot(f.fields || [], newField.colSpan || 6, itemHeight);
            const placedField = { ...newField, startCol: slot.startCol, rowIndex: slot.rowIndex };
            return { ...f, fields: normalizeLayout([...(f.fields || []), placedField]) };
          }
          if (f.fields) {
            return { ...f, fields: insertIntoParent(f.fields) };
          }
          return f;
        });
      };
      return normalizeLayout(insertIntoParent(prev));
    });
    setSelectedId(newField.id);
    toast.success(`Added ${newField.label} inside "${targetContainer.label}"`);
  }, [layout, currentTabId]);

  // Unified pointer drag handler for instant cross-container moves (group-to-group, group-to-canvas, canvas-to-group, group nesting)
  const handleUnifiedPointerDrag = useCallback((fieldId: string, parentId?: string) => (e: React.PointerEvent) => {
    if (activeTab !== 'builder') return;
    const startX = e.clientX;
    const startY = e.clientY;
    let hasMoved = false;

    const fieldToMove = findFieldRecursive(layoutRef.current, fieldId);
    if (!fieldToMove) return;

    const handlePointerMove = (moveEvt: PointerEvent) => {
      const dist = Math.hypot(moveEvt.clientX - startX, moveEvt.clientY - startY);
      if (dist < 6) return;
      if (!hasMoved) {
        hasMoved = true;
        setActiveDragItem({ type: 'existing_field', fieldId, fieldType: fieldToMove.type });
      }

      const elements = document.elementsFromPoint(moveEvt.clientX, moveEvt.clientY);
      const groupEl = elements.find(el => (el.hasAttribute('data-group-id') || el.hasAttribute('data-container-id')) && el.getAttribute('data-group-id') !== fieldId);
      const targetGroupId = groupEl?.getAttribute('data-group-id') || groupEl?.getAttribute('data-container-id') || undefined;
      const isOverMainCanvas = elements.some(el => el.id === 'main-grid-container');

      if (targetGroupId) {
        const rect = groupEl?.getBoundingClientRect() || { left: moveEvt.clientX, top: moveEvt.clientY, width: 800 };
        const { x, y } = snapToGrid(
          moveEvt.clientX - rect.left,
          moveEvt.clientY - rect.top,
          rect.width,
          GRID_CONFIG.rowHeight,
          GRID_CONFIG.gap,
          GRID_CONFIG.nestedPadding
        );
        setDragOverInfo({
          active: true,
          parentId: targetGroupId,
          col: x + 1,
          span: Math.min(fieldToMove.colSpan || 6, 12 - x),
          index: y,
          rowSpan: calculateHeight(fieldToMove)
        });
      } else if (isOverMainCanvas) {
        if (parentId) {
          const canvasEl = document.getElementById('main-grid-container');
          const rect = canvasEl?.getBoundingClientRect() || { left: 0, top: 0, width: 1100 };
          const { x, y } = snapToGrid(
            moveEvt.clientX - rect.left,
            moveEvt.clientY - rect.top,
            rect.width,
            GRID_CONFIG.rowHeight,
            GRID_CONFIG.gap,
            GRID_CONFIG.padding
          );
          setDragOverInfo({
            active: true,
            parentId: undefined,
            col: x + 1,
            span: Math.min(fieldToMove.colSpan || 6, 12 - x),
            index: y,
            rowSpan: calculateHeight(fieldToMove)
          });
        } else {
          setDragOverInfo(null);
        }
      } else {
        setDragOverInfo(null);
      }
    };

    const handlePointerUp = (upEvt: PointerEvent) => {
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('pointerup', handlePointerUp);
      setActiveDragItem(null);
      setDragOverInfo(null);
      setPreviewLayout(null);

      if (!hasMoved) return;

      const elements = document.elementsFromPoint(upEvt.clientX, upEvt.clientY);
      const groupEl = elements.find(el => (el.hasAttribute('data-group-id') || el.hasAttribute('data-container-id')) && el.getAttribute('data-group-id') !== fieldId);
      const targetGroupId = groupEl?.getAttribute('data-group-id') || groupEl?.getAttribute('data-container-id') || undefined;
      const isOverMainCanvas = elements.some(el => el.id === 'main-grid-container');

      const isDescendant = (parentField: Field, searchId: string): boolean => {
        if (parentField.id === searchId) return true;
        return (parentField.fields || []).some(f => isDescendant(f, searchId));
      };

      if (targetGroupId) {
        // Guard against circular nesting for container fields
        if (isContainerField(fieldToMove.type) && isDescendant(fieldToMove, targetGroupId)) {
          return;
        }

        const rect = groupEl?.getBoundingClientRect() || { left: upEvt.clientX, top: upEvt.clientY, width: 800 };
        const { x, y } = snapToGrid(
          upEvt.clientX - rect.left,
          upEvt.clientY - rect.top,
          rect.width,
          GRID_CONFIG.rowHeight,
          GRID_CONFIG.gap,
          GRID_CONFIG.nestedPadding
        );

        const updatedField: Field = {
          ...fieldToMove,
          parentId: targetGroupId,
          tabId: undefined,
          startCol: x + 1,
          rowIndex: y
        };

        setLayout(prevLayout => {
          const cleaned = removeFieldRecursive(prevLayout, fieldId);
          const insertIntoGroup = (fields: Field[]): Field[] => {
            return fields.map(f => {
              if (f.id === targetGroupId) {
                if (f.type === 'accordion' && updatedField.type !== 'group' && updatedField.type !== 'fieldGroup') {
                  if (!f.fields || f.fields.length === 0) {
                    const sectionId = `section-${Date.now()}`;
                    const fieldWithParent = { ...updatedField, parentId: sectionId };
                    const newSection: Field = {
                      id: sectionId,
                      type: 'group' as FieldType,
                      label: 'New Section 1',
                      name: `section_${Date.now()}`,
                      parentId: f.id,
                      fields: [fieldWithParent]
                    };
                    return { ...f, fields: [newSection] };
                  }
                  const firstSection = f.fields[0];
                  const fieldWithParent = { ...updatedField, parentId: firstSection.id };
                  const sectionFields = [...(firstSection.fields || []), fieldWithParent];
                  const resolved = resolveCollisionsInArray(fieldWithParent, sectionFields);
                  const updatedSections = f.fields.map((s, idx) => idx === 0 ? { ...s, fields: normalizeLayout(resolved) } : s);
                  return { ...f, fields: updatedSections };
                }
                const children = [...(f.fields || []), updatedField];
                const resolved = resolveCollisionsInArray(updatedField, children);
                return { ...f, fields: normalizeLayout(resolved) };
              }
              if (f.fields) {
                return { ...f, fields: insertIntoGroup(f.fields) };
              }
              return f;
            });
          };
          return insertIntoGroup(cleaned);
        });
        setSelectedId(fieldId);
      } else if (!targetGroupId && isOverMainCanvas && parentId) {
        // Dragging out of group to standalone root canvas
        const canvasEl = document.getElementById('main-grid-container');
        const rect = canvasEl?.getBoundingClientRect() || { left: 0, top: 0, width: 1100 };
        const { x, y } = snapToGrid(
          upEvt.clientX - rect.left,
          upEvt.clientY - rect.top,
          rect.width,
          GRID_CONFIG.rowHeight,
          GRID_CONFIG.gap,
          GRID_CONFIG.padding
        );

        const updatedField: Field = {
          ...fieldToMove,
          parentId: undefined,
          tabId: currentTabId,
          startCol: x + 1,
          rowIndex: y
        };

        setLayout(prevLayout => {
          const cleaned = removeFieldRecursive(prevLayout, fieldId);
          const sameTab = cleaned.filter(f => !f.parentId && (f.tabId === currentTabId || (!f.tabId && currentTabId === tabs[0]?.id)));
          const others = cleaned.filter(f => f.parentId || (f.tabId !== currentTabId && (f.tabId || currentTabId !== tabs[0]?.id)));
          const resolved = resolveCollisionsInArray(updatedField, [...sameTab, updatedField]);
          return [...others, ...normalizeLayout(resolved)];
        });
        setSelectedId(fieldId);
      }
    };

    window.addEventListener('pointermove', handlePointerMove);
    window.addEventListener('pointerup', handlePointerUp);
  }, [activeTab, currentTabId, tabs]);

  // DnD Handlers updated for flat grid system


  const handleDragOver = (e: React.DragEvent, parentId?: string, targetTabId?: string) => {
    e.preventDefault();
    e.stopPropagation();
    
    // Throttle layout generation state updates (e.g., maximum once per 75ms for smooth interpolation)
    const now = Date.now();
    if (now - lastDragOverTimeRef.current < 75) {
      return;
    }
    
    const isNested = !!parentId;
    const gridElement = (parentId 
      ? (document.getElementById(`canvas-nesting-${parentId}`) || document.getElementById(`canvas-field-${parentId}`)) 
      : targetTabId 
        ? document.getElementById(`section-grid-${targetTabId}`) 
        : document.getElementById('main-grid-container')) || (e.currentTarget as HTMLElement);
    
    const container = gridElement.getBoundingClientRect();
    
    const resolvedTabId = targetTabId || currentTabId;

    // Determine span and height from activeDragItem
    let span = 6;
    let draggedHeight = 2;

    if (activeDragItem) {
      if (activeDragItem.type === 'field') {
        const fieldDef = FIELD_CATEGORIES.flatMap(c => c.fields).find(f => f.id === activeDragItem.fieldType);
        if (fieldDef?.defaultSpan) span = fieldDef.defaultSpan;
        draggedHeight = calculateHeight({ type: activeDragItem.fieldType } as any);
      } else if (activeDragItem.type === 'move') {
        const field = layout.find(f => f.id === activeDragItem.fieldId) || findFieldRecursive(layout, activeDragItem.fieldId || '');
        if (field) {
          span = field.colSpan || 6;
          draggedHeight = calculateHeight(field);
        }
      }
    }

    let col = 1;
    let rowIndex = 0;
    let constrainedSpan = span;

    if (activeDragItem?.type === 'field') {
      // Place preview dropzone at the exact next available slot without moving existing fields
      const targetFields = parentId
        ? (findFieldRecursive(layout, parentId)?.fields || [])
        : layout.filter(f => !f.parentId && (f.tabId === resolvedTabId || (!f.tabId && resolvedTabId === tabs[0]?.id)));
      const slot = findNextAvailableSlot(targetFields, span, draggedHeight);
      col = slot.startCol;
      rowIndex = slot.rowIndex;
      constrainedSpan = span;
    } else {
      const { x, y } = snapToGrid(
        e.clientX - container.left,
        e.clientY - container.top,
        container.width,
        GRID_CONFIG.rowHeight,
        GRID_CONFIG.gap,
        isNested ? GRID_CONFIG.nestedPadding : GRID_CONFIG.padding
      );
      col = x + 1;
      rowIndex = y;
      constrainedSpan = Math.min(span, 13 - col);
    }

    const info = { 
      col, 
      span: constrainedSpan, 
      index: rowIndex, 
      active: true, 
      parentId,
      tabId: resolvedTabId,
      rowSpan: draggedHeight
    };

    // Ensure we don't spam updates if nothing changed
    if (dragOverInfo?.col === info.col && 
        dragOverInfo?.index === info.index && 
        dragOverInfo?.parentId === info.parentId &&
        dragOverInfo?.tabId === info.tabId &&
        dragOverInfo?.active === info.active) {
      return;
    }

    lastDragOverTimeRef.current = now;
    setDragOverInfo(info);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    // Only clear if we actually left the container
    if (e.relatedTarget && (e.currentTarget as HTMLElement).contains(e.relatedTarget as Node)) return;
    setDragOverInfo(null);
    setPreviewLayout(null);
  };

  const handleDropOnCanvas = (e: React.DragEvent, parentId?: string, targetTabId?: string) => {
    e.preventDefault();
    e.stopPropagation();
    setActiveDragItem(null);
    setDragOverInfo(null);
    setPreviewLayout(null);
    
    try {
      const data = JSON.parse(e.dataTransfer.getData('application/json'));
      const isNested = !!parentId;
      const gridElement = (parentId 
        ? (document.getElementById(`canvas-nesting-${parentId}`) || document.getElementById(`canvas-field-${parentId}`)) 
        : targetTabId 
          ? document.getElementById(`section-grid-${targetTabId}`) 
          : document.getElementById('main-grid-container')) || (e.currentTarget as HTMLElement);
      
      const container = gridElement.getBoundingClientRect();
      
      const { x, y } = snapToGrid(
        e.clientX - container.left,
        e.clientY - container.top,
        container.width,
        GRID_CONFIG.rowHeight,
        GRID_CONFIG.gap,
        isNested ? GRID_CONFIG.nestedPadding : GRID_CONFIG.padding
      );

      const dropCol = x + 1;
      const dropRow = y;

      const fieldId = data.type === 'move' ? data.fieldId : null;
      if (fieldId && fieldId === parentId) return;

      let fieldToInsert: Field | null = null;
      if (data.type === 'field') {
        fieldToInsert = createField(data.fieldType);
      } else if (fieldId) {
        fieldToInsert = findFieldRecursive(layout, fieldId) || null;
      }

      if (!fieldToInsert) return;

      // Prevent dropping container into itself or its own descendants
      if (fieldId && isContainerField(fieldToInsert.type) && parentId) {
        const isDescendant = (parentField: Field, searchId: string): boolean => {
          if (parentField.id === searchId) return true;
          return (parentField.fields || []).some(f => isDescendant(f, searchId));
        };
        if (isDescendant(fieldToInsert, parentId)) {
          return;
        }
      }

      const resolvedTabId = targetTabId || currentTabId;

      const isNewFromLibrary = data.type === 'field';
      const itemSpan = fieldToInsert.colSpan || (isContainerField(fieldToInsert.type) ? 12 : 6);
      const itemHeight = calculateHeight(fieldToInsert);

      const updatedField: Field = { 
        ...fieldToInsert, 
        colSpan: itemSpan,
        startCol: dropCol, 
        rowIndex: dropRow, 
        parentId: parentId || undefined,
        tabId: parentId ? undefined : resolvedTabId 
      };

      // Helper to insert field into the tree
      const performInsert = (fields: Field[], targetId?: string): { fields: Field[], insertedField?: Field } => {
        if (!targetId) {
          const sameTabFields = fields.filter(f => !f.parentId && (f.tabId === resolvedTabId || (!f.tabId && resolvedTabId === tabs[0]?.id)));
          const otherFields = fields.filter(f => f.parentId || !(f.tabId === resolvedTabId || (!f.tabId && resolvedTabId === tabs[0]?.id)));
          const placedField = isNewFromLibrary
            ? { ...updatedField, ...findNextAvailableSlot(sameTabFields, itemSpan, itemHeight) }
            : updatedField;
          const resolved = isNewFromLibrary
            ? [...sameTabFields, placedField]
            : resolveCollisionsInArray(placedField, [...sameTabFields, placedField]);
          return { 
            fields: [...otherFields, ...normalizeLayout(resolved)], 
            insertedField: placedField 
          };
        }
        
        let insertedField: Field | undefined;
        const nextFields = fields.map(f => {
          if (f.id === targetId) {
            if (f.type === 'accordion' && updatedField.type !== 'group' && updatedField.type !== 'fieldGroup') {
              if (!f.fields || f.fields.length === 0) {
                const sectionId = `section-${Date.now()}`;
                const fieldWithParent = { ...updatedField, parentId: sectionId, startCol: 1, rowIndex: 0 };
                const newSection: Field = {
                  id: sectionId,
                  type: 'group' as FieldType,
                  label: 'New Section 1',
                  name: `section_${Date.now()}`,
                  parentId: f.id,
                  fields: [fieldWithParent]
                };
                insertedField = fieldWithParent;
                return { ...f, fields: [newSection] };
              }
              const firstSection = f.fields[0];
              const placedInSection = isNewFromLibrary
                ? { ...updatedField, parentId: firstSection.id, ...findNextAvailableSlot(firstSection.fields || [], itemSpan, itemHeight) }
                : { ...updatedField, parentId: firstSection.id };
              const sectionFields = [...(firstSection.fields || []), placedInSection];
              const resolved = isNewFromLibrary ? sectionFields : resolveCollisionsInArray(placedInSection, sectionFields);
              insertedField = placedInSection;
              const updatedSections = f.fields.map((s, idx) => idx === 0 ? { ...s, fields: normalizeLayout(resolved) } : s);
              return { ...f, fields: updatedSections };
            }
            const placedNested = isNewFromLibrary
              ? { ...updatedField, ...findNextAvailableSlot(f.fields || [], itemSpan, itemHeight) }
              : updatedField;
            const nestedFields = [...(f.fields || []), placedNested];
            const resolved = isNewFromLibrary ? nestedFields : resolveCollisionsInArray(placedNested, nestedFields);
            insertedField = placedNested;
            return { ...f, fields: normalizeLayout(resolved) };
          }
          if (f.fields) {
            const result = performInsert(f.fields, targetId);
            if (result.insertedField) insertedField = result.insertedField;
            return { ...f, fields: result.fields };
          }
          return f;
        });
        return { fields: nextFields, insertedField };
      };

      if (parentId && !findFieldRecursive(layout, parentId)) return;

      let nextLayout = fieldId ? removeFieldRecursive(layout, fieldId) : [...layout];
      const result = performInsert(nextLayout, parentId);
      setLayout(normalizeLayout(result.fields));
      setSelectedId(fieldToInsert.id);
    } catch (err) {
      console.error('Drop error:', err);
    }
  };

  const findFieldRecursive = (fields: Field[], id: string): Field | undefined => {
    for (const f of fields) {
      if (f.id === id) return f;
      if (f.fields) {
        const found = findFieldRecursive(f.fields, id);
        if (found) return found;
      }
    }
    return undefined;
  };

  const removeFieldRecursive = (fields: Field[], id: string): Field[] => {
    return fields
      .filter(f => f.id !== id && f.id !== 'placeholder' && f.id !== '__drop_zone_indicator__' && f.type !== 'placeholder')
      .map(f => f.fields ? { ...f, fields: removeFieldRecursive(f.fields, id) } : f);
  };

  const cloneField = (id: string) => {
    const original = findFieldRecursive(layout, id);
    if (!original) return;

    const deepClone = (field: Field, pId?: string): Field => {
      const newId = generateId();
      const clonedField = {
        ...field,
        id: newId,
        parentId: pId
      };
      
      if (field.id === id) {
        clonedField.label = `${field.label} (Copy)`;
      }

      if (field.fields) {
        clonedField.fields = field.fields.map(f => deepClone(f, newId));
      }
      
      return clonedField;
    };

    const cloned = deepClone(original, original.parentId);
    // Position it at the end of the same container/tab
    cloned.rowIndex = 9999; 

    setLayout(prev => {
      // Find the container where the original field was
      const performInsert = (fields: Field[], targetParentId?: string): Field[] => {
        if (!targetParentId) {
          // It's a top-level field in a tab
          const sameTabFields = fields.filter(f => !f.parentId && f.tabId === original.tabId);
          const otherFields = fields.filter(f => f.parentId || f.tabId !== original.tabId);
          const nextSameTab = [...sameTabFields, cloned];
          // We don't really need resolveCollisions here since it's at rowIndex 9999, 
          // but normalizeLayout will handle it.
          return [...otherFields, ...normalizeLayout(nextSameTab)];
        }

        return fields.map(f => {
          if (f.id === targetParentId) {
            const nestedFields = [...(f.fields || []), cloned];
            return { ...f, fields: normalizeLayout(nestedFields) };
          }
          if (f.fields) {
            return { ...f, fields: performInsert(f.fields, targetParentId) };
          }
          return f;
        });
      };

      return normalizeLayout(performInsert([...prev], original.parentId));
    });

    setSelectedId(cloned.id);
    toast.success('Field duplicated');
  };

  const deleteBlocks = (ids: string[]) => {
    // Mapping safeguards: warn/block if mapped in triage rules
    const mappedRules: string[] = [];
    ids.forEach(fieldId => {
      allTenantAutomations.forEach(aut => {
        const routeAction = aut.actions?.find((a: any) => a.type === 'ROUTE_TO_MODULE');
        if (routeAction && routeAction.config?.targetModuleId === id) {
          const fieldMapping = routeAction.config.fieldMapping || {};
          if (fieldMapping.hasOwnProperty(fieldId)) {
            mappedRules.push(`"${aut.name}"`);
          }
        }
      });
    });

    if (mappedRules.length > 0) {
      toast.error(`Cannot delete field: It is actively mapped in Work Distribution rule(s): ${Array.from(new Set(mappedRules)).join(', ')}. Please update or remove those mappings first.`);
      return;
    }

    setLayout(prev => {
      let next = prev;
      ids.forEach(id => {
        next = removeFieldRecursive(next, id);
      });
      return normalizeLayout(next);
    });
    setSelectedIds([]);
  };

  const updateFields = (fieldIds: string[], updates: Partial<Field>) => {
    fieldIds.forEach(id => updateField(id, updates));
    
    // Sync with forms if required status changed
    if (updates.required !== undefined) {
      setForms(prev => prev.map(form => ({
        ...form,
        fields: (form.fields || []).map((f: any) => fieldIds.includes(f.id) ? { ...f, required: updates.required } : f),
        steps: (form.steps || []).map((step: any) => ({
          ...step,
          fields: (step.fields || []).map((f: any) => fieldIds.includes(f.id) ? { ...f, required: updates.required } : f)
        }))
      })));
    }
  };

  const updateField = (fieldId: string, updates: Partial<Field>) => {
    setLayout(prev => {
      // 1. Recursive update function
      const findAndUpdate = (fields: Field[]): Field[] => {
        return fields.map(f => {
          if (f.id === fieldId) {
            const newUpdates = { ...updates };
            
            // If label is changing and name hasn't been manually edited, auto-generate slug
            if (updates.label !== undefined && !f.isNameManuallyEdited && updates.name === undefined) {
              newUpdates.name = generateSlug(updates.label, layout, fieldId);
            }
            
            // If name is being manually updated, mark it as manually edited
            if (updates.name !== undefined) {
              newUpdates.isNameManuallyEdited = true;
            }
            
            return { ...f, ...newUpdates };
          }
          if (f.fields) {
            return { ...f, fields: findAndUpdate(f.fields) };
          }
          return f;
        });
      };

      // 2. Perform the update
      const updatedLayout = findAndUpdate(prev);
      
      // 3. Re-normalize the entire layout tree bottom-up
      // This ensures that any height changes in nested fields propagate to parents 
      // and their siblings, preventing overlaps.
      return normalizeLayout(updatedLayout);
    });

    // Sync with forms if required status changed
    if (updates.required !== undefined) {
      setForms(prev => prev.map(form => ({
        ...form,
        fields: (form.fields || []).map((f: any) => f.id === fieldId ? { ...f, required: updates.required } : f),
        steps: (form.steps || []).map((step: any) => ({
          ...step,
          fields: (step.fields || []).map((f: any) => f.id === fieldId ? { ...f, required: updates.required } : f)
        }))
      })));
    }
  };

  const selectedField = selectedId ? findFieldRecursive(layout, selectedId) : null;
  const parentField = (selectedField && selectedField.parentId) ? findFieldRecursive(layout, selectedField.parentId) : null;
  const isAccordionSection = selectedField?.type === 'group' && parentField?.type === 'accordion';
  const selectedTab = selectedId ? tabs.find(t => t.id === selectedId) : null;

  const updateTab = (tabId: string, updates: Partial<Tab>) => {
    if (updates.parentId) {
      const parentId = updates.parentId;
      const targetAlreadyHasSubtabs = tabs.some(t => t.parentId === parentId);
      if (!targetAlreadyHasSubtabs) {
        setLayout(prev => prev.map(f => f.tabId === parentId ? { ...f, tabId } : f));
      }
    }
    setTabs(prev => prev.map(t => t.id === tabId ? { ...t, ...updates } : t));
  };

